using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
public static class OpenRPGTorchPrefabImportV137 {
 [Serializable] public class Request {public string output,prefab_path,prefab_guid;public string[] unresolved_guids;}
 [Serializable] public class Identity {public string type,guid,file_id,name;}
 [Serializable] public class TextureBinding {public string property,declared_default;public bool explicitly_null;public Identity texture;public int width,height,mips;public string format,filter,wrap_u,wrap_v;public int anisotropy;public float mip_bias;}
 [Serializable] public class MaterialInfo {public Identity material,shader;public string serialized_json;public TextureBinding[] texture_bindings;}
 [Serializable] public class ComponentInfo {public Identity identity;public string serialized_json;}
 [Serializable] public class Node {public string path,name;public Matrix4x4 local_to_world;public Vector3 local_position,local_scale;public Quaternion local_rotation;public ComponentInfo[] components;public MaterialInfo[] materials;}
 [Serializable] public class Unresolved {public string guid,asset_path;}
 [Serializable] public class Report {public string unity_version,prefab_guid;public Node[] nodes;public Unresolved[] unresolved;public int transforms,particle_systems,mesh_renderers,mesh_filters,lights,mesh_colliders,lod_groups;public bool original_prefab_components_unchanged,authoring_version_parity=false,runtime_converted=false,full_import=false;}
 static Identity Id(UnityEngine.Object o){if(o==null)return null;string g;long f;if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out g,out f))throw new Exception("Persistent native identity unavailable: "+o.GetType().FullName);return new Identity{type=o.GetType().FullName,guid=g,file_id=f.ToString(System.Globalization.CultureInfo.InvariantCulture),name=o.name};}
 static MaterialInfo Mat(Material m){if(m==null)throw new Exception("Missing source material");var shader=m.shader;if(shader==null)throw new Exception("Missing source shader");var textures=new List<TextureBinding>();for(int i=0;i<shader.GetPropertyCount();i++){if(shader.GetPropertyType(i)!=ShaderPropertyType.Texture)continue;string name=shader.GetPropertyName(i);var t=m.GetTexture(name);var info=new TextureBinding{property=name,declared_default=shader.GetPropertyTextureDefaultName(i),explicitly_null=t==null,texture=Id(t)};var t2=t as Texture2D;if(t2!=null){info.width=t2.width;info.height=t2.height;info.mips=t2.mipmapCount;info.format=t2.graphicsFormat.ToString();info.filter=t2.filterMode.ToString();info.wrap_u=t2.wrapModeU.ToString();info.wrap_v=t2.wrapModeV.ToString();info.anisotropy=t2.anisoLevel;info.mip_bias=t2.mipMapBias;}textures.Add(info);}return new MaterialInfo{material=Id(m),shader=Id(shader),serialized_json=EditorJsonUtility.ToJson(m,true),texture_bindings=textures.ToArray()};}
 static void Walk(Transform t,string path,List<Node> nodes){var components=t.GetComponents<Component>();if(components.Any(c=>c==null))throw new Exception("Missing native component at "+path);nodes.Add(new Node{path=path,name=t.name,local_to_world=t.localToWorldMatrix,local_position=t.localPosition,local_scale=t.localScale,local_rotation=t.localRotation,components=components.Select(c=>new ComponentInfo{identity=Id(c),serialized_json=EditorJsonUtility.ToJson(c,true)}).ToArray(),materials=t.GetComponent<Renderer>()==null?new MaterialInfo[0]:t.GetComponent<Renderer>().sharedMaterials.Select(Mat).ToArray()});for(int i=0;i<t.childCount;i++)Walk(t.GetChild(i),path+"/"+i,nodes);}
 public static void Export(){var args=Environment.GetCommandLineArgs();int index=Array.IndexOf(args,"--openrpg-manifest");if(index<0)throw new Exception("Manifest absent");var r=JsonUtility.FromJson<Request>(File.ReadAllText(args[index+1]));if(File.Exists(r.output))throw new Exception("Preserve prior native receipt");var unresolved=r.unresolved_guids.Select(g=>new Unresolved{guid=g,asset_path=AssetDatabase.GUIDToAssetPath(g)}).ToArray();if(unresolved.Any(u=>!string.IsNullOrEmpty(u.asset_path)))throw new Exception("Unresolved original dependency unexpectedly resolves in shared project");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(r.prefab_path);if(prefab==null)throw new Exception("Private original prefab absent");var id=Id(prefab);if(id.guid!=r.prefab_guid)throw new Exception("Private prefab GUID differs");int transforms=prefab.GetComponentsInChildren<Transform>(true).Length,particles=prefab.GetComponentsInChildren<ParticleSystem>(true).Length,renderers=prefab.GetComponentsInChildren<MeshRenderer>(true).Length,filters=prefab.GetComponentsInChildren<MeshFilter>(true).Length,lights=prefab.GetComponentsInChildren<Light>(true).Length,colliders=prefab.GetComponentsInChildren<MeshCollider>(true).Length,lods=prefab.GetComponentsInChildren<LODGroup>(true).Length;if(transforms!=8||particles!=2||renderers!=4||filters!=4||lights!=1||colliders!=1||lods!=1)throw new Exception("Complete source hierarchy differs");var all=prefab.GetComponentsInChildren<Component>(true);if(all.Any(c=>c==null))throw new Exception("Missing source component");var before=all.Select(c=>EditorJsonUtility.ToJson(c,true)).ToArray();var nodes=new List<Node>();Walk(prefab.transform,"root",nodes);if(!before.SequenceEqual(all.Select(c=>EditorJsonUtility.ToJson(c,true))))throw new Exception("Source components mutated during inspection");File.WriteAllText(r.output,JsonUtility.ToJson(new Report{unity_version=Application.unityVersion,prefab_guid=id.guid,nodes=nodes.ToArray(),unresolved=unresolved,transforms=transforms,particle_systems=particles,mesh_renderers=renderers,mesh_filters=filters,lights=lights,mesh_colliders=colliders,lod_groups=lods,original_prefab_components_unchanged=true},true));}
}
